const fila = $input.all().find(i => i.json && i.json.telegram_user_id);

if (!fila) {
  return [{ json: { hayFormulario: false } }];
}

return [{ json: { ...fila.json, hayFormulario: true } }];

const input = $input.first().json;

let data = input.output ?? input;
if (typeof data === 'string') {
  // Si el modelo escribió el JSON dentro de un bloque ```json, lo tomamos de ahí
  const bloque = data.match(/```json\s*([\s\S]*?)```/);
  const crudo = bloque ? bloque[1] : data;
  try {
    data = JSON.parse(crudo.trim());
  } catch (e) {
    data = { mensaje: data.split('```')[0] };
  }
}

// Texto plano: sin negritas ni bloques de código que rompan Telegram
const limpiar = t => String(t ?? '').replace(/\*\*/g, '').replace(/```/g, '').trim();
const mensaje = limpiar(data.mensaje);

const partes = mensaje.split('|||').map(p => p.trim()).filter(p => p.length > 0);

const derivaciones = ['ninguna', 'venta', 'reclamo', 'consulta'];
const rutas = ['listo_para_comprar', 'evaluacion', 'exploratorio', 'recurrente', 'queja'];
const promos = ['ninguna', 'primera_compra', 'segundo_par', 'recompra'];

const valor = v => String(v ?? '').toLowerCase().trim();

const derivar = derivaciones.includes(valor(data.derivar)) ? valor(data.derivar) : 'ninguna';
const ruta = rutas.includes(valor(data.ruta)) ? valor(data.ruta) : null;
const promocion_ofrecida = promos.includes(valor(data.promocion_ofrecida))
  ? valor(data.promocion_ofrecida)
  : 'ninguna';

return [{
  json: {
    part1: partes[0] || '',
    part2: partes[1] || '',
    part3: partes[2] || '',
    venta_realizada: data.venta_realizada === true,
    derivar,
    ruta,
    promocion_ofrecida,
    detalle: limpiar(data.detalle)
  }
}];

const entrada = $input.first().json;

const origen = entrada.puntaje_nps !== undefined && entrada.puntaje_nps !== null
  ? 'nps'
  : 'conversacion';

return [{ json: { ...entrada, origen } }];

const ctx = $('Conversación o NPS?1').first().json;
