// El Structured Output Parser deja el objeto dentro de "output"; si no, viene como texto
let data = raw.output ?? raw.text ?? raw;
if (typeof data === 'string') {
  try {
    data = JSON.parse(data.replace(/```json|```/g, '').trim());
  } catch (e) {
    data = {};
  }
}

// Normaliza: minúsculas, sin tildes, guion o espacio -> guion bajo
const norm = v => String(v ?? '')
  .toLowerCase().trim()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[-\s]+/g, '_');

const permitidos = {
  sentimiento: ['positivo', 'neutro', 'negativo'],
  intencion: ['alta', 'media', 'baja'],
  etapa_funnel: ['awareness', 'consideracion', 'decision', 'post_venta'],
  objecion_principal: ['precio', 'stock', 'talle', 'envio', 'confianza', 'ninguna', 'otra'],
  prioridad: ['alta', 'media', 'baja'],
  clasificacion: ['fidelizacion', 'sugerencia', 'observacion', 'post_venta', 'reclamo', 'ninguna'],
};

const resultado = {};
const errores = [];

for (const [campo, valores] of Object.entries(permitidos)) {
  const valor = norm(data[campo] ?? (campo === 'clasificacion' ? 'ninguna' : ''));
