    resultado[campo] = valor;
  } else {
    resultado[campo] = null;
    errores.push(`${campo}: "${data[campo]}"`);
  }
}

const resumen = String(data.resumen ?? '').trim();
const accion = String(data.accion_recomendada ?? '').trim();
if (!resumen) errores.push('resumen vacío');
if (!accion) errores.push('accion_recomendada vacía');

return [{
  json: {
    telegram_user_id: ctx.telegram_user_id,
    evento_id: ctx.evento_id ?? null,
    origen: ctx.origen,
    ...resultado,
    resumen,
    accion_recomendada: accion,
    valido: errores.length === 0,
    errores,
  },
}];

