const campo = etiqueta => {
  const m = detalle.match(new RegExp(etiqueta + '\\s*:\\s*([^|]+)', 'i'));
  return m ? m[1].trim() : '';
};

return [{
  json: {
    modelo: campo('Producto'),
    categoria: campo('Categoría'),
    talle: campo('Talle').replace(/\D/g, ''),
    cantidad: parseInt(campo('Cantidad'), 10) || 0,
    monto: parseFloat(campo('Monto total').replace(/\./g, '').replace(',', '.')) || 0
  }
}];

const pedido = $('Parsear Detalle de la compra1').first().json;
const tipoCliente = $('Tipo Cliente1').first().json.tipo_cliente;

// Promociones: se calculan con los datos, no con lo que diga el agente
const candidatas = [
  { nombre: 'primera_compra', porcentaje: 10, aplica: tipoCliente === 'nuevo' },
  { nombre: 'recompra',       porcentaje: 15, aplica: tipoCliente === 'recurrente' },
  { nombre: 'segundo_par',    porcentaje: 15, aplica: pedido.cantidad >= 2 && /urbano/i.test(pedido.categoria) },
].filter(p => p.aplica);

// No se acumulan entre sí: gana la de mayor porcentaje
const principal = candidatas.sort((a, b) => b.porcentaje - a.porcentaje)[0] ?? null;

return [{
  json: {
    ...pedido,
    descuento_aplicado: principal ? `${principal.porcentaje}%` : 'false',
    promos_aplicadas: principal ? [principal.nombre] : [],
  },
}];

